import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.launch
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.RequestBody.Companion.toRequestBody
import java.util.UUID
import javax.inject.Inject
enum class EditorTool{CALIBRATE,WALKABLE,OBSTACLE,NODE,DESTINATION}
data class EditorState(val venueId:String="",val floorId:String?=null,val map:FloorMap?=null,val pixelsX:Int=0,val pixelsY:Int=0,val calibrated:Boolean=false,val tool:EditorTool=EditorTool.CALIBRATE,val points:List<Point2D> = emptyList(),val metres:String="",val destination:String="",val nodeType:NodeType=NodeType.INTERSECTION,val undo:List<FloorMap> = emptyList(),val error:String?=null,val message:String?=null)
sealed interface EditorAction{data class Open(val id:String):EditorAction;data class Upload(val c:Context,val u:Uri):EditorAction;data class Tool(val t:EditorTool):EditorAction;data class Tap(val p:Point2D):EditorAction;data class Metres(val v:String):EditorAction;data class DestinationName(val v:String):EditorAction;data class NodeKind(val v:NodeType):EditorAction;data object Finish:EditorAction;data object Connect:EditorAction;data object Undo:EditorAction;data object Save:EditorAction;data object Publish:EditorAction;data class Closure(val id:String,val v:Boolean):EditorAction}
class EditorRepository @Inject constructor(private val api:AraiapApi){suspend fun venue(id:String)=apiCall{api.venue(id)};suspend fun draft(id:String)=apiCall{api.draft(id)};suspend fun upload(c:Context,id:String,u:Uri)=apiCall{val type=c.contentResolver.getType(u)?:error("Unknown type");require(type=="image/png"||type=="image/jpeg");val b=c.contentResolver.openInputStream(u)!!.use{it.readBytes()};require(b.size<=15*1024*1024);api.uploadFloorPlan(id,floorPlanPart("floor-plan",type,b.toRequestBody(type.toMediaType())))};suspend fun save(m:FloorMap)=apiCall{api.saveDraft(m.id,m.copy(routeEdges=normalizedEdges(m)))};suspend fun publish(id:String)=apiCall{api.publish(id)};suspend fun close(f:String,e:String,v:Boolean)=apiCall{api.setClosure(f,e,ClosureRequest(v))}}
@HiltViewModel class FloorEditorViewModel @Inject constructor(private val repo:EditorRepository):ViewModel(){var state by mutableStateOf(EditorState());private set
 fun dispatch(a:EditorAction){when(a){is EditorAction.Open->open(a.id);is EditorAction.Tool->state=state.copy(tool=a.t,points=emptyList());is EditorAction.Metres->state=state.copy(metres=a.v);is EditorAction.DestinationName->state=state.copy(destination=a.v);is EditorAction.NodeKind->state=state.copy(nodeType=a.v);is EditorAction.Upload->upload(a.c,a.u);is EditorAction.Tap->tap(a.p);EditorAction.Finish->finish();EditorAction.Connect->connect();EditorAction.Undo->{state.undo.lastOrNull()?.let{state=state.copy(map=it,undo=state.undo.dropLast(1))}};EditorAction.Save->save();EditorAction.Publish->publish();is EditorAction.Closure->closure(a.id,a.v)}}
 private fun open(id:String)=viewModelScope.launch{state=state.copy(venueId=id);when(val v=repo.venue(id)){is NetworkResult.Failure->state=state.copy(error=v.message);is NetworkResult.Success->{val floorId=v.value.floorId?:return@launch;when(val d=repo.draft(floorId)){is NetworkResult.Success->state=state.copy(floorId=floorId,map=d.value,calibrated=d.value.widthMeters>0,message="Draft loaded.");is NetworkResult.Failure->state=state.copy(floorId=floorId,error=d.message)}}}} 
 private fun mutate(m:FloorMap){val old=state.map?:return;state=state.copy(map=m,undo=state.undo+old,error=null)}
 private fun upload(c:Context,u:Uri)=viewModelScope.launch{when(val r=repo.upload(c,state.venueId,u)){is NetworkResult.Success->{val x=r.value;state=state.copy(floorId=x.floorId,pixelsX=x.widthPixels,pixelsY=x.heightPixels,map=FloorMap(x.floorId,state.venueId,0,MapStatus.DRAFT,x.widthPixels.toDouble(),x.heightPixels.toDouble(),x.imageUrl),message="Tap two calibration points.")}is NetworkResult.Failure->state=state.copy(error=r.message)}}
 private fun tap(p:Point2D){val m=state.map?:return;when(state.tool){EditorTool.CALIBRATE->{val ps=(state.points+p).takeLast(2);state=state.copy(points=ps);if(ps.size==2){val real=state.metres.toDoubleOrNull();if(real==null||real<=0)state=state.copy(error="Enter a positive distance.")else{val c=Calibration(state.pixelsX,state.pixelsY,ps[0].distanceTo(ps[1]),real);mutate(m.copy(widthMeters=c.widthMeters,heightMeters=c.heightMeters));state=state.copy(points=emptyList(),calibrated=true)}}};EditorTool.WALKABLE,EditorTool.OBSTACLE->state=state.copy(points=state.points+p);EditorTool.NODE->mutate(m.copy(routeNodes=m.routeNodes+RouteNode(UUID.randomUUID().toString(),p.x,p.y,state.nodeType)));EditorTool.DESTINATION->{val n=m.routeNodes.filter{it.type==NodeType.DOOR}.minByOrNull{it.point.distanceTo(p)};if(n==null||n.point.distanceTo(p)>1||state.destination.isBlank())state=state.copy(error="Place a named destination within 1 metre of a door node.")else mutate(m.copy(destinations=m.destinations+Destination(UUID.randomUUID().toString(),state.destination,p.x,p.y,n.id)))}}}
 private fun finish(){val m=state.map?:return;if(state.points.size<3){state=state.copy(error="Polygon needs three points.");return};val p=Polygon2D(UUID.randomUUID().toString(),state.points);mutate(if(state.tool==EditorTool.WALKABLE)m.copy(walkableAreas=m.walkableAreas+p)else m.copy(obstacles=m.obstacles+p));state=state.copy(points=emptyList())}
 private fun connect(){val m=state.map?:return;if(m.routeNodes.size<2)return;val a=m.routeNodes[m.routeNodes.lastIndex-1];val b=m.routeNodes.last();mutate(m.copy(routeEdges=m.routeEdges+RouteEdge(UUID.randomUUID().toString(),a.id,b.id,a.point.distanceTo(b.point),true,false)))}
 private fun save(){val m=state.map?:return;if(!state.calibrated){state=state.copy(error="Calibrate before saving.");return};viewModelScope.launch{when(val r=repo.save(m)){is NetworkResult.Success->state=state.copy(map=r.value,message="Draft saved.");is NetworkResult.Failure->state=state.copy(error=r.message)}}}
 private fun publish(){val m=state.map?:return;val issues=PublishValidator.validate(m);if(!state.calibrated||issues.isNotEmpty()){state=state.copy(error=issues.firstOrNull()?.message?:"Calibrate first.");return};viewModelScope.launch{when(val r=repo.publish(m.id)){is NetworkResult.Success->state=state.copy(map=r.value,message="Version ${r.value.version} published.");is NetworkResult.Failure->state=state.copy(error=r.message)}}}
 private fun closure(id:String,v:Boolean){val f=state.floorId?:return;viewModelScope.launch{when(val r=repo.close(f,id,v)){is NetworkResult.Success->state=state.copy(map=r.value,message="Closure published.");is NetworkResult.Failure->state=state.copy(error=r.message)}}}
}
@Composable fun FloorEditorScreen(venueId:String,vm:FloorEditorViewModel=hiltViewModel()){val c=LocalContext.current;val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let{vm.dispatch(EditorAction.Upload(c,it))}};LaunchedEffect(venueId){vm.dispatch(EditorAction.Open(venueId))};val s=vm.state;Column(Modifier.fillMaxSize().padding(12.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Floor editor",style=MaterialTheme.typography.headlineMedium);Button({pick.launch(arrayOf("image/png","image/jpeg"))}){Text("Upload floor plan")};s.map?.let{m->FloorMapCanvas(m,s.points,null,Modifier.fillMaxWidth().height(350.dp),onMapTap={vm.dispatch(EditorAction.Tap(it))});Row{EditorTool.entries.forEach{FilterChip(s.tool==it,{vm.dispatch(EditorAction.Tool(it))},{Text(it.name.lowercase())})}};if(s.tool==EditorTool.CALIBRATE)OutlinedTextField(s.metres,{vm.dispatch(EditorAction.Metres(it))},label={Text("Known metres")});if(s.tool==EditorTool.NODE)Row{NodeType.entries.forEach{FilterChip(s.nodeType==it,{vm.dispatch(EditorAction.NodeKind(it))},{Text(it.name)})}};if(s.tool==EditorTool.DESTINATION)OutlinedTextField(s.destination,{vm.dispatch(EditorAction.DestinationName(it))},label={Text("Destination name")});if(s.tool==EditorTool.WALKABLE||s.tool==EditorTool.OBSTACLE)Button({vm.dispatch(EditorAction.Finish)}){Text("Finish polygon")};Button({vm.dispatch(EditorAction.Connect)}){Text("Connect last nodes")};m.routeEdges.forEach{e->Row{Text("${e.fromNodeId.take(4)} to ${e.toNodeId.take(4)}",Modifier.weight(1f));Switch(e.temporarilyClosed,{vm.dispatch(EditorAction.Closure(e.id,it))})}};Row{Button({vm.dispatch(EditorAction.Undo)}){Text("Undo")};Button({vm.dispatch(EditorAction.Save)}){Text("Save")};Button({vm.dispatch(EditorAction.Publish)}){Text("Publish")}}};s.message?.let{Text(it)};s.error?.let{Text(it,color=MaterialTheme.colorScheme.error)}}}
